import{I as e,P as t,Q as n,n as r}from"./chunks/framework.Bz7b9rhL.js";var i=JSON.parse(`{"title":"Getting Started","description":"","frontmatter":{"id":"guide.getting-started","title":"Getting Started","describes":["proposal.0001"]},"headers":[],"relativePath":"guides/getting-started.md","filePath":"guides/getting-started.md"}`),a={name:`guides/getting-started.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h1><h2 id="i-just-cloned-this-what-do-i-do" tabindex="-1">I just cloned this. What do I do? <a class="header-anchor" href="#i-just-cloned-this-what-do-i-do" aria-label="Permalink to “I just cloned this. What do I do?”">​</a></h2><p>Start by making the kit your project, then use it for one small feature. You and the agent have different jobs, but you use the same orientation command whenever the work needs a next step.</p><h2 id="what-workbench-is" tabindex="-1">What Workbench is <a class="header-anchor" href="#what-workbench-is" aria-label="Permalink to “What Workbench is”">​</a></h2><p>Workbench is a process kit for developing a project with a coding agent. No single artifact defines a feature: intent is written more than once in forms that can disagree. A proposal records intent, tests encode behavior, guides explain it, and code implements it; disagreement between them is the signal to investigate.</p><p>For the argument behind this structure, read the <code>README.md</code>. This guide starts with using it.</p><h2 id="install-and-verify" tabindex="-1">Install and verify <a class="header-anchor" href="#install-and-verify" aria-label="Permalink to “Install and verify”">​</a></h2><p><a href="https://mise.jdx.dev" target="_blank" rel="noreferrer">Mise</a> owns the toolchain and every task. Install it once per machine, following the <a href="https://mise.jdx.dev/getting-started.html" target="_blank" rel="noreferrer">mise guide</a>:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">curl</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> https://mise.run</span><span style="--shiki-dark:#F97583;--shiki-light:#c62739;"> |</span><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;"> sh</span></span></code></pre></div><p>From the repository root, provision the pinned tools. <code>mise.toml</code> pins them and <code>mise.lock</code> pins the exact downloads, so every machine and every CI runner gets the same versions — Node, pnpm, <a href="https://bun.sh" target="_blank" rel="noreferrer">Bun</a> (one test loads the <code>workflow</code> tool through Oh My Pi&#39;s real loader, and that loader runs on Bun), the <a href="https://cli.github.com" target="_blank" rel="noreferrer">GitHub CLI</a>, <a href="https://hk.jdx.dev" target="_blank" rel="noreferrer">hk</a>, <a href="https://fnox.jdx.dev" target="_blank" rel="noreferrer">Fnox</a>, <a href="https://github.com/steveyegge/beads" target="_blank" rel="noreferrer">Beads</a> and <a href="https://worktrunk.dev" target="_blank" rel="noreferrer">Worktrunk</a>:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> install</span></span></code></pre></div><p>Then bootstrap the repository. This installs the npm dependencies with the pinned pnpm, initializes the Beads work tracker, and installs every git hook — including the <code>commit-msg</code> hook that holds commits to <a href="https://scopedcommits.com/" target="_blank" rel="noreferrer">Scoped Commits</a>. It is idempotent; run it again whenever the tooling changes:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> setup</span></span></code></pre></div><p>Then run the complete local gate:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> check</span></span></code></pre></div><p><code>mise run check</code> succeeds only when formatting, lint, and type checks, record validation, tests, and the documentation build all finish without an error. The documentation build also catches dead links.</p><p><strong><code>gh</code> still needs your credentials.</strong> The process runs on pull requests, so authenticate it against your remote:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">gh</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> auth</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> login</span></span></code></pre></div><p>Without it, <code>mise run status</code> cannot see the pull request and will say so rather than guess.</p><p>When you need to diagnose the nonformatting parts of the gate, run:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> validate</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> test</span></span></code></pre></div><p>This repository produced this trimmed passing output:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>$ node tools/validate.ts</span></span>
<span class="line"><span>Validation passed: 0 violations</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ node --test &#39;tools/**/*.test.ts&#39;</span></span>
<span class="line"><span>ℹ tests 120</span></span>
<span class="line"><span>ℹ pass 120</span></span>
<span class="line"><span>ℹ fail 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ vitest run --dir .omp/tools</span></span>
<span class="line"><span> Test Files  4 passed (4)</span></span>
<span class="line"><span>      Tests  107 passed (107)</span></span></code></pre></div><p><code>mise tasks</code> lists everything available. Run <code>mise run check</code> after changing the project; the agent runs it before claiming a feature is ready.</p><h3 id="if-the-gate-fails" tabindex="-1">If the gate fails <a class="header-anchor" href="#if-the-gate-fails" aria-label="Permalink to “If the gate fails”">​</a></h3><p>Do not begin a feature with a failing baseline. Give the output to the agent and have it find the root cause; changing a gate or suppressing its failure is not a repair.</p><h2 id="adapt-it-to-your-harness" tabindex="-1">Adapt it to your harness <a class="header-anchor" href="#adapt-it-to-your-harness" aria-label="Permalink to “Adapt it to your harness”">​</a></h2><p>Workbench comes wired for <a href="https://omp.sh" target="_blank" rel="noreferrer">Oh My Pi</a>: it loads the contract, discovers the skills, and runs the lifecycle extensions in <code>.omp/extensions/</code> with no further setup. For any other harness, adapt its contract and skill-loading configuration, commit that one-time setup, and then forget about the wiring; the process material in <code>.agents/</code> remains the source of truth. Follow <a href="./adapting-your-harness">Adapting Your Harness</a> before starting feature work.</p><h2 id="read-the-worked-example" tabindex="-1">Read the worked example <a class="header-anchor" href="#read-the-worked-example" aria-label="Permalink to “Read the worked example”">​</a></h2><p>This clone ships Workbench&#39;s own record and guides, which are the clearest available answer to what good output looks like. Read them before you write or delete anything: <code>VISION.md</code> for the shape of a vision, <code>proposals/0001-*.md</code> for a real proposal, and <a href="./running-a-feature">Running a Feature</a> for the loop you are about to run.</p><h2 id="write-your-project-s-vision" tabindex="-1">Write your project&#39;s vision <a class="header-anchor" href="#write-your-project-s-vision" aria-label="Permalink to “Write your project&#39;s vision”">​</a></h2><p>Now replace <code>VISION.md</code>, using <code>.agents/templates/VISION.md</code>, in conversation with the agent. Describe your project&#39;s purpose, minimum viable product, principles, direction, and non-goals — not a list of the first feature&#39;s tasks.</p><p>The vision is the standard against which later proposals are evaluated. Without it, the agent silently substitutes its assumptions for the direction you did not write down. Keep it current when accepted work changes what the project is.</p><h2 id="clear-the-rest-of-the-example" tabindex="-1">Clear the rest of the example <a class="header-anchor" href="#clear-the-rest-of-the-example" aria-label="Permalink to “Clear the rest of the example”">​</a></h2><p>Remove <code>proposals/0001-*.md</code> and the six guides. <strong>Keep <code>guides/README.md</code></strong> — it documents the frontmatter every future guide needs, and the site&#39;s navigation points at it while you have no guides of your own. Keep the <code>README.md</code> in each record directory for the same reason.</p><p>Keep <code>policies/</code> and <code>decisions/</code> empty until a real feature establishes one; speculative policies are the ones nobody follows.</p><h2 id="run-your-first-feature" tabindex="-1">Run your first feature <a class="header-anchor" href="#run-your-first-feature" aria-label="Permalink to “Run your first feature”">​</a></h2><p>Pick something small for the first pass. It will expose the parts your harness handles badly, and learning that on a small change is much cheaper than learning it on a large one.</p><p>The <a href="./running-a-feature">Running a Feature</a> guide you just read takes a change from a branch and draft pull request through proposal, implementation, review, release, and cleanup. The agent handles the ordered implementation and review work; you establish intent, make the proposal decisions reserved for you, and review the preview before accepting the feature.</p><h2 id="the-one-command" tabindex="-1">The one command <a class="header-anchor" href="#the-one-command" aria-label="Permalink to “The one command”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">mise</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> status</span></span></code></pre></div><p>Run it with no arguments at the start of a session and whenever you need to orient yourself. It reads the branch, pull request, and proposal record, then reports the current phase, the next action, and who acts.</p><p>You are not expected to memorise commands, skill names, or process steps. “Keep going” is a complete instruction to the agent because it orients itself with the same command.</p><h2 id="where-things-live" tabindex="-1">Where things live <a class="header-anchor" href="#where-things-live" aria-label="Permalink to “Where things live”">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>What it holds</th><th>When you use it</th></tr></thead><tbody><tr><td><code>VISION.md</code></td><td>Your project&#39;s purpose, minimum viable product, and direction</td><td>Write it before feature work; update it after accepted work changes the project.</td></tr><tr><td><code>proposals/</code></td><td>One numbered specification for each change</td><td>Write and settle a proposal before implementation.</td></tr><tr><td><code>guides/</code></td><td>Reader-facing behavior and usage guides</td><td>The agent writes or updates these from the proposal before code.</td></tr><tr><td><code>policies/</code></td><td>Rules future work must keep enforcing</td><td>Add one only when a feature establishes a durable rule.</td></tr><tr><td><code>decisions/</code></td><td>Architectural choices and their context</td><td>Add one only when a feature establishes a durable choice.</td></tr><tr><td><code>.agents/</code></td><td>Harness-neutral process instructions, rules, and templates</td><td>Your harness reads the adapted copy; this remains the source of truth.</td></tr></tbody></table><h2 id="continue-from-here" tabindex="-1">Continue from here <a class="header-anchor" href="#continue-from-here" aria-label="Permalink to “Continue from here”">​</a></h2><ul><li><a href="./running-a-feature">Run a feature</a></li><li><a href="./writing-a-good-proposal">Write a good proposal</a></li><li><a href="./choosing-a-preview">Choose a preview</a></li><li><a href="./keeping-the-record">Keep the record</a></li><li><a href="./adapting-your-harness">Adapt your harness</a></li></ul>`,47)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};